import{_ as o,o as e,c as s,a2 as i}from"./chunks/framework.DA69LXMH.js";const u=JSON.parse('{"title":"Guia de Instalação (.exe & Desktop)","description":"","frontmatter":{},"headers":[],"relativePath":"guia/instalacao.md","filePath":"guia/instalacao.md"}'),t={name:"guia/instalacao.md"};function r(n,a,l,d,c,p){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="guia-de-instalacao-exe-desktop" tabindex="-1">Guia de Instalação (.exe &amp; Desktop) <a class="header-anchor" href="#guia-de-instalacao-exe-desktop" aria-label="Permalink to &quot;Guia de Instalação (.exe &amp; Desktop)&quot;">​</a></h1><p>A distribuição do <strong>EchoBot</strong> foi construída no modelo desktop &quot;Zero-Config&quot; para Windows: você não precisa instalar manualmente servidores de banco de dados, interpretadores externos ou pacotes complexos de desenvolvimento.</p><hr><h2 id="📥-passo-1-download-da-versao-oficial" tabindex="-1">📥 Passo 1: Download da Versão Oficial <a class="header-anchor" href="#📥-passo-1-download-da-versao-oficial" aria-label="Permalink to &quot;📥 Passo 1: Download da Versão Oficial&quot;">​</a></h2><ol><li>Acesse o repositório de lançamentos no GitHub: <a href="https://github.com/mukasc/EchoBotReleases/releases" target="_blank" rel="noreferrer">Releases Oficiais do EchoBot</a>.</li><li>Localize a versão mais recente com a tag <strong><code>Latest</code></strong>.</li><li>Na seção de <strong>Assets</strong>, faça o download do instalador: <ul><li><strong>Instalador Completo:</strong> <code>EchoBot-Setup-vX.X.X.exe</code></li><li><em>(Opcional)</em> <strong>Versão Portátil:</strong> <code>EchoBot-Portable-vX.X.X.zip</code></li></ul></li></ol><hr><h2 id="🛠️-passo-2-executando-o-instalador" tabindex="-1">🛠️ Passo 2: Executando o Instalador <a class="header-anchor" href="#🛠️-passo-2-executando-o-instalador" aria-label="Permalink to &quot;🛠️ Passo 2: Executando o Instalador&quot;">​</a></h2><ol><li>Dê um duplo clique no arquivo executável baixado.</li><li>Caso o Windows SmartScreen exiba o aviso <em>&quot;O Windows protegeu o seu computador&quot;</em>, clique em: <ul><li><strong>Mais informações</strong> ➔ <strong>Executar assim mesmo</strong>.</li></ul></li><li>Siga as instruções do assistente do Inno Setup escolhendo o diretório de destino desejado (por padrão em <code>Arquivos de Programas</code>).</li><li>Ao concluir, marque a opção para <strong>Iniciar o EchoBot</strong>.</li></ol><hr><h2 id="🚀-passo-3-inicializacao-launcher-na-bandeja" tabindex="-1">🚀 Passo 3: Inicialização &amp; Launcher na Bandeja <a class="header-anchor" href="#🚀-passo-3-inicializacao-launcher-na-bandeja" aria-label="Permalink to &quot;🚀 Passo 3: Inicialização &amp; Launcher na Bandeja&quot;">​</a></h2><p>Ao ser iniciado, o EchoBot opera através de um launcher desktop silencioso:</p><ul><li><strong>Ícone na Bandeja do Sistema (System Tray):</strong> Um ícone do EchoBot aparecerá ao lado do relógio do Windows.</li><li><strong>Menu de Controle Rápido:</strong><ul><li><strong>Abrir Dashboard:</strong> Inicia o navegador padrão diretamente na interface do Mestre em <code>http://localhost:8000</code>.</li><li><strong>Ver Logs:</strong> Abre o Console Administrativo de diagnóstico em tempo real (<code>/logs</code>).</li><li><strong>Reiniciar Motores:</strong> Reinicia os serviços de API e do Whisper Sidecar de forma controlada.</li><li><strong>Encerrar:</strong> Finaliza todos os processos em segundo plano com liberação imediata de memória.</li></ul></li><li><strong>Abertura Automática:</strong> O navegador abrirá a tela inicial na primeira inicialização.</li></ul><hr><h2 id="📂-onde-ficam-salvos-os-meus-dados" tabindex="-1">📂 Onde ficam salvos os meus dados? <a class="header-anchor" href="#📂-onde-ficam-salvos-os-meus-dados" aria-label="Permalink to &quot;📂 Onde ficam salvos os meus dados?&quot;">​</a></h2><p>Para facilitar backups, migrações e privacidade:</p><ul><li>Por padrão, todas as suas campanhas, artigos de compêndio, gravações e modelos ficam armazenados em:<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%LOCALAPPDATA%\\EchoBotData</span></span></code></pre></div></li><li>Se desejar transferir seus dados para outro disco rígido ou SSD com mais espaço, você pode utilizar o assistente automático em <strong>Configurações ➔ Armazenamento ➔ Migrar Dados</strong>.</li></ul><hr><h2 id="🐳-alternativa-execucao-via-docker-linux-servidor" tabindex="-1">🐳 Alternativa: Execução via Docker (Linux / Servidor) <a class="header-anchor" href="#🐳-alternativa-execucao-via-docker-linux-servidor" aria-label="Permalink to &quot;🐳 Alternativa: Execução via Docker (Linux / Servidor)&quot;">​</a></h2><p>Se você preferir rodar o EchoBot em um servidor local com Docker:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Para servidores com aceleração NVIDIA GPU:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.gpu.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Para servidores em modo CPU:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>Acesse a aplicação no navegador em <code>http://localhost:8000</code>.</p>`,21)])])}const m=o(t,[["render",r]]);export{u as __pageData,m as default};
